#include <vector>

class Solution {
public:
    int selfDivisiblePermutationCount(int n) {
        std::vector<int> memo(1 << (n + 1), -1);
        auto dfs = [&](auto& self, int mask) -> int {
            int i = __builtin_popcount(mask) + 1;
            if (i > n) return 1;
            if (memo[mask] != -1) return memo[mask];
            int res = 0;
            for (int j = 1; j <= n; ++j) {
                if (((mask >> j) & 1) == 0 && (i % j == 0 || j % i == 0)) {
                    res += self(self, mask | (1 << j));
                }
            }
            return memo[mask] = res;
        };
        return dfs(dfs, 0);
    }
};

import java.util.Arrays;

class Solution {
    private int[] memo;
    private int n;

    public int selfDivisiblePermutationCount(int n) {
        this.n = n;
        memo = new int[1 << (n + 1)];
        Arrays.fill(memo, -1);
        return dfs(0);
    }

    private int dfs(int mask) {
        int i = Integer.bitCount(mask) + 1;
        if (i > n) return 1;
        if (memo[mask] != -1) return memo[mask];
        int res = 0;
        for (int j = 1; j <= n; j++) {
            if (((mask >> j) & 1) == 0 && (i % j == 0 || j % i == 0)) {
                res += dfs(mask | (1 << j));
            }
        }
        return memo[mask] = res;
    }
}

var selfDivisiblePermutationCount = function(n) {
    const memo = new Map();
    function dfs(mask) {
        let count = 0;
        let tmp = mask;
        while (tmp > 0) {
            count += tmp & 1;
            tmp >>= 1;
        }
        const i = count + 1;
        if (i > n) return 1;
        if (memo.has(mask)) return memo.get(mask);
        let res = 0;
        for (let j = 1; j <= n; j++) {
            if (!((mask >> j) & 1) && (i % j === 0 || j % i === 0)) {
                res += dfs(mask | (1 << j));
            }
        }
        memo.set(mask, res);
        return res;
    }
    return dfs(0);
};
